basicCode.vanilla:
import { createAgentPlan } from '@/components/ui/agent-plan';

const plan = createAgentPlan({ steps, labels });

// Lista vazia não desenha nada: uma lista com zero itens promete o que não há.
if (plan) document.querySelector('#app')?.append(plan);

withLabelsCode.web:
// Os passos são DADO: quem trabalha manda a lista, e a peça a desenha.
const steps = [
  { id: 's1', label: 'Ler o relatório de custos', state: 'done' },
  { id: 's2', label: 'Comparar com o trimestre anterior', state: 'running' },
  {
    id: 's3',
    label: 'Buscar o histórico no arquivo antigo',
    state: 'skipped',
    detail: 'O relatório já trazia os doze meses.',
  },
  { id: 's4', label: 'Escrever o resumo', state: 'pending' },
];

// A palavra de cada um dos cinco estados, e o nome acessível da lista.
const labels = {
  plan: 'Plano',
  state: {
    pending: 'A fazer',
    running: 'Fazendo',
    done: 'Feito',
    failed: 'Falhou',
    skipped: 'Pulado',
  },
};

extensibilityCode.web:
// O QUE JÁ NÃO PODE MUDAR sai do vocabulário compartilhado, e não de um `if`
// da tela: o passo ATUAL é o primeiro que ainda não terminou.
isStepFinished('pending');  // false → ainda pode virar qualquer coisa
isStepFinished('running');  // false → está acontecendo agora
isStepFinished('done');     // true
isStepFinished('failed');   // true
isStepFinished('skipped');  // true  → não aconteceu, e não vai mais

// Pulado é FIM, e não ausência: o passo fica na lista com o motivo, porque
// sumir com ele reescreveria o plano depois do fato.

customizationCode.web:
.nds-agent-plan {
  max-inline-size: 32rem;
}

/* O marcador é REFORÇO, e não a pista: a palavra ao lado é o que descreve o
   passo. Mexer no marcador não muda o que chega a quem ouve. */
.nds-agent-plan-step[data-state="running"] .nds-agent-plan-marker {
  animation: nds-thinking-pulse var(--duration-slow) var(--ease-standard) infinite;
}

